def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each non-background edge cell casts inward along its row/column;
    # rays color background 3 and convert the first isolated dot to 4.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    sources = []
    for c in range(w):
        if grid[0][c] != bg: sources.append((0,c,1,0))
        if grid[h-1][c] != bg: sources.append((h-1,c,-1,0))
    for r in range(h):
        if grid[r][0] != bg: sources.append((r,0,0,1))
        if grid[r][w-1] != bg: sources.append((r,w-1,0,-1))
    for r,c,dr,dc in sources:
        rr,cc=r+dr,c+dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] != bg:
                if rr not in (0,h-1) and cc not in (0,w-1): out[rr][cc]=4
                break
            out[rr][cc]=3
            rr+=dr; cc+=dc
    return out
