    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # For each top-edge bar column, connect only to an aligned interior dot.
    # Color the gap with the dot's color and replace the dot with 4.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    for c in range(w):
        if grid[0][c] == bg:
            continue
        for r in range(1, h-1):
            if grid[r][c] != bg:
                color = grid[r][c]
                for rr in range(1, r):
                    out[rr][c] = color
                out[r][c] = 4
                break
    return out
