 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Join isolated interior points to any boundary streak on the same row or
    # column. Color the gap with the point's color and replace the point by 4.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color == 9:
                continue
            if any(grid[0][cc] != 9 for cc in range(w)):
                # Top edge streak: only a point in a streak's column is aligned.
                if grid[0][c] != 9:
                    for rr in range(1, r):
                        out[rr][c] = color
                    out[r][c] = 4
            if any(grid[h-1][cc] != 9 for cc in range(w)) and grid[h-1][c] != 9:
                for rr in range(r+1, h-1):
                    out[rr][c] = color
                out[r][c] = 4
            if grid[r][0] != 9:
                for cc in range(1, c):
                    out[r][cc] = color
                out[r][c] = 4
            if grid[r][w-1] != 9:
                for cc in range(c+1, w-1):
                    out[r][cc] = color
                out[r][c] = 4
    return out
